        assertNull(view.getTemplateName());
        assertNull(view.getTemplateEngine());
        assertNull(view.getNullableResponseMaxChunkSize());
        assertTrue(view.getStaticVariables().isEmpty());
        assertFalse(view.isDefaultCharsetSet());
        assertFalse(view.isSupportedMediaTypesSet());

        assertEquals(Integer.MAX_VALUE, ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);
        assertEquals(Integer.MAX_VALUE, view.getResponseMaxChunkSizeBytes());
        assertEquals(StandardCharsets.UTF_8, view.getDefaultCharset());
    }


