    @Test
    void renderInFullModeWritesTheEngineOutputWithASingleWriteWithCall() {

        final RenderFixture fixture = new RenderFixture();
        fixture.engine.setOutput(buffers("Hello World"));

        final Map<String, Object> model = new LinkedHashMap<>();
        model.put("name", "World");

        fixture.view.render(model, TEXT_HTML_UTF8, fixture.exchange).block();

        assertEquals(1, fixture.engine.invocations.size());
        final ProcessStreamInvocation invocation = fixture.engine.lastInvocation();
        assertEquals("test-template", invocation.template);
        assertNull(invocation.markupSelectors);
        assertSame(fixture.exchange.response.bufferFactory(), invocation.bufferFactory);
        assertEquals(TEXT_HTML_UTF8, invocation.mediaType);
        assertEquals(StandardCharsets.UTF_8, invocation.charset);
        assertEquals(Integer.MAX_VALUE, invocation.responseMaxChunkSizeBytes);
        assertEquals("World", invocation.context.getVariable("name"));

        assertEquals(1, fixture.exchange.response.writeWithInvocations.size());
        assertTrue(fixture.exchange.response.writeAndFlushWithInvocations.isEmpty());
        assertEquals("Hello World", bodyOf(fixture.exchange.response.writeWithInvocations.get(0)));

        assertEquals(TEXT_HTML_UTF8, fixture.exchange.response.getHeaders().getContentType());
        assertEquals(Locale.US, fixture.exchange.response.getHeaders().getContentLanguage());
    }


    @Test
    void renderWithAChunkSizeLimitWritesAndFlushesEverySingleEngineBuffer() {

        final RenderFixture fixture = new RenderFixture();
        fixture.view.setResponseMaxChunkSizeBytes(4);
        fixture.engine.setOutput(buffers("abcd", "efgh"));

        fixture.view.render(Collections.emptyMap(), TEXT_HTML_UTF8, fixture.exchange).block();

        assertEquals(4, fixture.engine.lastInvocation().responseMaxChunkSizeBytes);

        assertTrue(fixture.exchange.response.writeWithInvocations.isEmpty());
        assertEquals(1, fixture.exchange.response.writeAndFlushWithInvocations.size());

        final Publisher<? extends Publisher<? extends DataBuffer>> flushed =
                fixture.exchange.response.writeAndFlushWithInvocations.get(0);
        assertEquals(2L, Flux.from(flushed).count().block().longValue());
        assertEquals("abcdefgh", flushedBodyOf(flushed));
    }


