    @Test
    void renderExposesSpringRequestContextAndEvaluationContextAsVariables() {

        final RenderFixture fixture = new RenderFixture();
        final Map<String, Object> model = new LinkedHashMap<>();
        model.put("name", "World");

        fixture.view.render(model, TEXT_HTML_UTF8, fixture.exchange).block();

        final IContext context = fixture.engine.lastInvocation().context;

        final Object springRequestContext =
                context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT);
        assertTrue(springRequestContext instanceof RequestContext);
        assertEquals("World", ((RequestContext) springRequestContext).getModel().get("name"));

