        final Object evaluationContext = context.getVariable(
                ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME);
        assertTrue(evaluationContext instanceof ThymeleafEvaluationContext);
        assertSame(fixture.applicationContext,
                ((ThymeleafEvaluationContext) evaluationContext).getApplicationContext());
    }


