    @Test
    void renderResolvesPublisherSupplierAndFunctionReactiveModelAdditions() {

        final RenderFixture fixture = new RenderFixture();

        final AtomicReference<ServerWebExchange> exchangeSeenByFunction = new AtomicReference<>();
        final Map<String, Object> executionAttributes = new LinkedHashMap<>();
        executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("publishedAttribute"),
                Flux.just("published"));
        executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("suppliedAttribute"),
                (Supplier<Publisher<?>>) () -> Mono.just("supplied"));
        executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("functionAttribute"),
                (Function<ServerWebExchange, Publisher<?>>) exchange -> {
                    exchangeSeenByFunction.set(exchange);
                    return Mono.just("computed");
                });
        executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("unsupportedAttribute"),
                "not-a-publisher");
        executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("nullAttribute"),
                null);
        executionAttributes.put("notAReactiveModelAddition", Flux.just("ignored"));

        fixture.engine.addDialect(new TestExecutionAttributeDialect(executionAttributes));

        fixture.view.render(Collections.emptyMap(), TEXT_HTML_UTF8, fixture.exchange).block();

        final IContext context = fixture.engine.lastInvocation().context;
        assertEquals(Collections.singletonList("published"), context.getVariable("publishedAttribute"));
        assertEquals("supplied", context.getVariable("suppliedAttribute"));
        assertEquals("computed", context.getVariable("functionAttribute"));
        assertSame(fixture.exchange, exchangeSeenByFunction.get());
        assertFalse(context.containsVariable("unsupportedAttribute"));
        assertFalse(context.containsVariable("nullAttribute"));
        assertFalse(context.containsVariable("notAReactiveModelAddition"));
    }




