    private static Publisher<DataBuffer> buffers(final String... parts) {
        final DefaultDataBufferFactory bufferFactory = new DefaultDataBufferFactory();
        return Flux.fromArray(parts)
                .map(part -> bufferFactory.wrap(part.getBytes(StandardCharsets.UTF_8)));
    }


    private static String bodyOf(final Publisher<? extends DataBuffer> publisher) {
        final DataBuffer buffer = DataBufferUtils.join(Flux.from(publisher)).block();
        if (buffer == null) {
            return "";
        }
        final byte[] bytes = new byte[buffer.readableByteCount()];
        buffer.read(bytes);
        DataBufferUtils.release(buffer);
        return new String(bytes, StandardCharsets.UTF_8);
    }


    private static String flushedBodyOf(final Publisher<? extends Publisher<? extends DataBuffer>> publisher) {
        return bodyOf(Flux.from(publisher).concatMap(inner -> Flux.from(inner)));
    }




