    private static final class ProcessStreamInvocation {

        final String template;
        final Set<String> markupSelectors;
        final IContext context;
        final DataBufferFactory bufferFactory;
        final MediaType mediaType;
        final Charset charset;
        final int responseMaxChunkSizeBytes;

        ProcessStreamInvocation(final String template, final Set<String> markupSelectors, final IContext context,
                                final DataBufferFactory bufferFactory, final MediaType mediaType, final Charset charset,
                                final int responseMaxChunkSizeBytes) {
            this.template = template;
            this.markupSelectors = markupSelectors;
            this.context = context;
            this.bufferFactory = bufferFactory;
            this.mediaType = mediaType;
            this.charset = charset;
            this.responseMaxChunkSizeBytes = responseMaxChunkSizeBytes;
        }

    }




    private static final class RecordingTemplateEngine extends SpringWebFluxTemplateEngine {

        final List<ProcessStreamInvocation> invocations = new ArrayList<>();

        private Publisher<DataBuffer> output = Flux.empty();

        void setOutput(final Publisher<DataBuffer> output) {
            this.output = output;
        }

        ProcessStreamInvocation lastInvocation() {
            assertFalse(this.invocations.isEmpty(), "The template engine has not been invoked");
            return this.invocations.get(this.invocations.size() - 1);
        }

        @Override
        public Publisher<DataBuffer> processStream(
                final String template, final Set<String> markupSelectors, final IContext context,
                final DataBufferFactory bufferFactory, final MediaType mediaType, final Charset charset,
                final int responseMaxChunkSizeBytes) {
            this.invocations.add(new ProcessStreamInvocation(
                    template, markupSelectors, context, bufferFactory, mediaType, charset,
                    responseMaxChunkSizeBytes));
            return this.output;
        }

    }




