        view.setMarkupSelector("  content  ");

        assertEquals("reactiveView", view.getBeanName());
        assertEquals("template", view.getTemplateName());
        assertEquals(Locale.CANADA_FRENCH, view.getLocale());
        assertEquals(1024, view.getResponseMaxChunkSizeBytes());
        assertEquals(Integer.valueOf(1024), view.getNullableResponseMaxChunkSize());
        assertEquals("content", view.getMarkupSelector());

