            final SpringWebFluxTemplateEngine engine, final String templateName) {

        final StaticApplicationContext applicationContext = new StaticApplicationContext();
        applicationContext.refresh();

        final ThymeleafReactiveView view = new ThymeleafReactiveView();
        view.setApplicationContext(applicationContext);
        view.setTemplateEngine(engine);
        view.setTemplateName(templateName);
        view.setLocale(Locale.FRENCH);
