    private static SpringWebFluxTemplateEngine newEngine(final Map<String, Object> executionAttributeAdditions) {

        final SpringWebFluxTemplateEngine engine = new SpringWebFluxTemplateEngine();

        if (!executionAttributeAdditions.isEmpty()) {
            engine.setDialect(new SpringStandardDialect() {
                @Override
                public Map<String, Object> getExecutionAttributes() {
                    final Map<String, Object> attributes = new LinkedHashMap<>(super.getExecutionAttributes());
                    attributes.putAll(executionAttributeAdditions);
                    return attributes;
                }
            });
        }

        final StringTemplateResolver templateResolver = new StringTemplateResolver();
        templateResolver.setTemplateMode(TemplateMode.HTML);
        templateResolver.setCacheable(false);
        engine.setTemplateResolver(templateResolver);
        return engine;
    }


