    /*
     * ------------------------------------------------------------------------------------
     * BASIC BUILDING / EMPTY CONFIGURATION
     * ------------------------------------------------------------------------------------
     */

    @Test
    @DisplayName("build() rejects a null dialect configuration set")
    public void buildRejectsNullDialectConfigurationSet() {
        final IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> DialectSetConfiguration.build(null));
        assertEquals("Dialect configuration set cannot be null", exception.getMessage());
    }

    @Test
    @DisplayName("build() with no dialects produces an empty but fully usable configuration")
    public void buildWithNoDialectsProducesEmptyConfiguration() {

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(new LinkedHashSet<DialectConfiguration>());

        assertNotNull(configuration);
        assertTrue(configuration.getDialectConfigurations().isEmpty());
        assertTrue(configuration.getDialects().isEmpty());
        assertFalse(configuration.isStandardDialectPresent());
        assertNull(configuration.getStandardDialectPrefix());
        assertTrue(configuration.getExecutionAttributes().isEmpty());
        assertNull(configuration.getExpressionObjectFactory().getAllExpressionObjectNames());
        assertNull(configuration.getExpressionObjectFactory().buildObject(null, "anything"));
        assertFalse(configuration.getExpressionObjectFactory().isCacheable("anything"));

        assertNotNull(configuration.getElementDefinitions());
        assertNotNull(configuration.getAttributeDefinitions());

        for (final TemplateMode templateMode : TemplateMode.values()) {
            assertTrue(configuration.getTemplateBoundariesProcessors(templateMode).isEmpty());
            assertTrue(configuration.getCDATASectionProcessors(templateMode).isEmpty());
            assertTrue(configuration.getCommentProcessors(templateMode).isEmpty());
            assertTrue(configuration.getDocTypeProcessors(templateMode).isEmpty());
            assertTrue(configuration.getElementProcessors(templateMode).isEmpty());
            assertTrue(configuration.getProcessingInstructionProcessors(templateMode).isEmpty());
            assertTrue(configuration.getTextProcessors(templateMode).isEmpty());
            assertTrue(configuration.getXMLDeclarationProcessors(templateMode).isEmpty());
            assertTrue(configuration.getPreProcessors(templateMode).isEmpty());
            assertTrue(configuration.getPostProcessors(templateMode).isEmpty());
        }

    }

    @Test
    @DisplayName("A dialect implementing no dialect feature is still registered")
    public void plainDialectIsRegistered() {

        final IDialect dialect = new TestDialect("plain");

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(dialect)));

        assertEquals(1, configuration.getDialects().size());
        assertSame(dialect, configuration.getDialects().iterator().next());
        assertFalse(configuration.isStandardDialectPresent());
        assertNull(configuration.getStandardDialectPrefix());
    }

    @Test
    @DisplayName("The returned dialect configuration set is unmodifiable and keeps configuration instances")
    public void dialectConfigurationsAreUnmodifiable() {

        final DialectConfiguration dialectConfiguration = new DialectConfiguration(new TestDialect("plain"));

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(dialectConfiguration));

        assertEquals(1, configuration.getDialectConfigurations().size());
        assertSame(dialectConfiguration, configuration.getDialectConfigurations().iterator().next());
        assertThrows(UnsupportedOperationException.class,
                () -> configuration.getDialectConfigurations().add(new DialectConfiguration(new TestDialect("other"))));

    }

    @Test
    @DisplayName("The returned dialects set is unmodifiable")
    public void dialectsAreUnmodifiable() {

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(new TestDialect("plain"))));

        assertThrows(UnsupportedOperationException.class,
