    @Test
    @DisplayName("The input dialect configuration set is defensively copied")
    public void inputDialectConfigurationSetIsCopied() {

        final Set<DialectConfiguration> input = configurations(new DialectConfiguration(new TestDialect("first")));

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(input);

        input.add(new DialectConfiguration(new TestDialect("second")));

        assertEquals(1, configuration.getDialectConfigurations().size());
        assertEquals(1, configuration.getDialects().size());

    }

    @Test
    @DisplayName("Two configurations of the very same dialect are kept as configurations but the dialect is not duplicated")
    public void sameDialectInTwoConfigurationsIsNotDuplicatedInDialects() {

