    @Test
    @DisplayName("The dialect default prefix is used when no prefix is specified in the configuration")
    public void dialectDefaultPrefixIsUsedWhenNotSpecified() {

        final TestProcessorDialect dialect = processorDialect(
                "prefix-dialect", "dd", 100,
                new TestElementTagProcessor(TemplateMode.HTML, "dd", null, "action", 100, "element"));

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(dialect)));

        assertTrue(dialect.processorsRequested);
        assertEquals("dd", dialect.requestedPrefix);

        final IElementProcessor processor = configuration.getElementProcessors(TemplateMode.HTML).iterator().next();
        final MatchingAttributeName matchingAttributeName = processor.getMatchingAttributeName();
        assertNotNull(matchingAttributeName);
        assertEquals("action", matchingAttributeName.getMatchingAttributeName().getAttributeName());
        assertEquals("dd", matchingAttributeName.getMatchingAttributeName().getPrefix());
    }

    @Test
    @DisplayName("The prefix specified in the configuration overrides the dialect default prefix")
    public void configuredPrefixOverridesDialectDefaultPrefix() {

        final TestProcessorDialect dialect = processorDialect(
                "prefix-dialect", "dd", 100,
                new TestElementTagProcessor(TemplateMode.HTML, "custom", null, "action", 100, "element"));

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(
                configurations(new DialectConfiguration("custom", dialect)));

        assertTrue(dialect.processorsRequested);
        assertEquals("custom", dialect.requestedPrefix);

        final IElementProcessor processor = configuration.getElementProcessors(TemplateMode.HTML).iterator().next();
        final MatchingAttributeName matchingAttributeName = processor.getMatchingAttributeName();
        assertNotNull(matchingAttributeName);
        assertEquals("custom", matchingAttributeName.getMatchingAttributeName().getPrefix());
    }

