    @Test
    @DisplayName("Each dialect processor is routed to the set corresponding to its processor interface")
    public void processorsAreRoutedToTheirSpecificSets() {

        final IProcessor elementTag = new TestElementTagProcessor(TemplateMode.HTML, "dd", "div", null, 100, "element-tag");
        final IProcessor elementModel = new TestElementModelProcessor(TemplateMode.HTML, "dd", "section", null, 200, "element-model");
        final IProcessor boundaries = new TestTemplateBoundariesProcessor(TemplateMode.HTML, 300, "boundaries");
        final IProcessor cdata = new TestCDATASectionProcessor(TemplateMode.HTML, 400, "cdata");
        final IProcessor comment = new TestCommentProcessor(TemplateMode.HTML, 500, "comment");
        final IProcessor docType = new TestDocTypeProcessor(TemplateMode.HTML, 600, "doctype");
        final IProcessor instruction = new TestProcessingInstructionProcessor(TemplateMode.HTML, 700, "pi");
        final IProcessor text = new TestTextProcessor(TemplateMode.HTML, 800, "text");
        final IProcessor xmlDeclaration = new TestXMLDeclarationProcessor(TemplateMode.HTML, 900, "xmldecl");

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(processorDialect("routing", "dd", 100,
                        elementTag, elementModel, boundaries, cdata, comment, docType, instruction, text, xmlDeclaration))));

        final Set<IElementProcessor> elementProcessors = configuration.getElementProcessors(TemplateMode.HTML);
        assertEquals(2, elementProcessors.size());
        assertTrue(containsInstanceOf(elementProcessors, org.thymeleaf.processor.element.IElementTagProcessor.class));
        assertTrue(containsInstanceOf(elementProcessors, org.thymeleaf.processor.element.IElementModelProcessor.class));

        assertEquals(1, configuration.getTemplateBoundariesProcessors(TemplateMode.HTML).size());
        assertTrue(configuration.getTemplateBoundariesProcessors(TemplateMode.HTML).iterator().next() instanceof ITemplateBoundariesProcessor);

        assertEquals(1, configuration.getCDATASectionProcessors(TemplateMode.HTML).size());
        assertTrue(configuration.getCDATASectionProcessors(TemplateMode.HTML).iterator().next() instanceof ICDATASectionProcessor);

        assertEquals(1, configuration.getCommentProcessors(TemplateMode.HTML).size());
        assertTrue(configuration.getCommentProcessors(TemplateMode.HTML).iterator().next() instanceof ICommentProcessor);

        assertEquals(1, configuration.getDocTypeProcessors(TemplateMode.HTML).size());
        assertTrue(configuration.getDocTypeProcessors(TemplateMode.HTML).iterator().next() instanceof IDocTypeProcessor);

        assertEquals(1, configuration.getProcessingInstructionProcessors(TemplateMode.HTML).size());
        assertTrue(configuration.getProcessingInstructionProcessors(TemplateMode.HTML).iterator().next() instanceof IProcessingInstructionProcessor);

        assertEquals(1, configuration.getTextProcessors(TemplateMode.HTML).size());
        assertTrue(configuration.getTextProcessors(TemplateMode.HTML).iterator().next() instanceof ITextProcessor);

        assertEquals(1, configuration.getXMLDeclarationProcessors(TemplateMode.HTML).size());
        assertTrue(configuration.getXMLDeclarationProcessors(TemplateMode.HTML).iterator().next() instanceof IXMLDeclarationProcessor);

        assertEquals(0, configuration.getPreProcessors(TemplateMode.HTML).size());
        assertEquals(0, configuration.getPostProcessors(TemplateMode.HTML).size());

        for (final IProcessor processor : allProcessors(configuration, TemplateMode.HTML)) {
            assertEquals(TemplateMode.HTML, processor.getTemplateMode());
        }
    }

    @Test
    @DisplayName("Processors are kept separate for each template mode")
    public void processorsAreSeparatedByTemplateMode() {

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(processorDialect("modes", "dd", 100,
                        new TestTextProcessor(TemplateMode.HTML, 100, "html-text"),
                        new TestTextProcessor(TemplateMode.TEXT, 100, "text-text"),
                        new TestTextProcessor(TemplateMode.JAVASCRIPT, 100, "js-text")))));

        assertEquals(1, configuration.getTextProcessors(TemplateMode.HTML).size());
        assertEquals("html-text", configuration.getTextProcessors(TemplateMode.HTML).iterator().next().toString());

        assertEquals(1, configuration.getTextProcessors(TemplateMode.TEXT).size());
        assertEquals("text-text", configuration.getTextProcessors(TemplateMode.TEXT).iterator().next().toString());

        assertEquals(1, configuration.getTextProcessors(TemplateMode.JAVASCRIPT).size());
        assertEquals("js-text", configuration.getTextProcessors(TemplateMode.JAVASCRIPT).iterator().next().toString());

        assertTrue(configuration.getTextProcessors(TemplateMode.XML).isEmpty());
        assertTrue(configuration.getTextProcessors(TemplateMode.CSS).isEmpty());
        assertTrue(configuration.getTextProcessors(TemplateMode.RAW).isEmpty());
    }

