    @Test
    @DisplayName("Execution attributes of all dialects are merged")
    public void executionAttributesAreMerged() {

        final Map<String, Object> first = new LinkedHashMap<String, Object>();
        first.put("first", Integer.valueOf(1));
        first.put("second", "two");

        final Map<String, Object> second = new LinkedHashMap<String, Object>();
        second.put("third", Boolean.TRUE);

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(new TestExecutionAttributeDialect("attrs1", first)),
                new DialectConfiguration(new TestExecutionAttributeDialect("attrs2", second))));

        assertEquals(Arrays.asList("first", "second", "third"),
                new ArrayList<String>(configuration.getExecutionAttributes().keySet()));
        assertEquals(Integer.valueOf(1), configuration.getExecutionAttribute("first"));
        assertEquals("two", configuration.getExecutionAttribute("second"));
        assertEquals(Boolean.TRUE, configuration.getExecutionAttribute("third"));

        assertTrue(configuration.hasExecutionAttribute("first"));
        assertTrue(configuration.hasExecutionAttribute("third"));
        assertFalse(configuration.hasExecutionAttribute("missing"));
        assertNull(configuration.getExecutionAttribute("missing"));
    }

