        final TestExpressionObjectFactory factory = new TestExpressionObjectFactory(
                "single", names("#strings", "#numbers"), true);

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(new TestExpressionObjectDialect("expr", factory))));

        final IExpressionObjectFactory expressionObjectFactory = configuration.getExpressionObjectFactory();
