        assertTrue(expressionObjectFactory.isCacheable("#strings"));
    }

    @Test
    @DisplayName("Expression object factories from several dialects are aggregated")
    public void expressionObjectFactoriesAreAggregated() {

        final TestExpressionObjectFactory first = new TestExpressionObjectFactory(
                "first", names("firstOnly", "shared"), true);
        final TestExpressionObjectFactory second = new TestExpressionObjectFactory(
                "second", names("secondOnly", "shared"), false);

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(new TestExpressionObjectDialect("expr1", first)),
                new DialectConfiguration(new TestExpressionObjectDialect("expr2", second))));

        final IExpressionObjectFactory expressionObjectFactory = configuration.getExpressionObjectFactory();
        assertNotNull(expressionObjectFactory);

        assertEquals(new HashSet<String>(Arrays.asList("firstOnly", "secondOnly", "shared")),
                expressionObjectFactory.getAllExpressionObjectNames());

        assertEquals("first:firstOnly", expressionObjectFactory.buildObject(null, "firstOnly"));
        assertEquals("second:secondOnly", expressionObjectFactory.buildObject(null, "secondOnly"));
        assertNull(expressionObjectFactory.buildObject(null, "missing"));

        assertFalse(expressionObjectFactory.isCacheable("shared"));
        assertTrue(expressionObjectFactory.isCacheable("firstOnly"));
        assertFalse(expressionObjectFactory.isCacheable("secondOnly"));
    }

    @Test
