        assertSame(configuration.getElementDefinitions(), preProcessor.getElementDefinitions());
        assertSame(configuration.getAttributeDefinitions(), preProcessor.getAttributeDefinitions());

        assertSame(configuration.getElementDefinitions(), postProcessor.getElementDefinitions());
        assertSame(configuration.getAttributeDefinitions(), postProcessor.getAttributeDefinitions());
    }



