                DialectSetConfiguration.build(new LinkedHashSet<DialectConfiguration>());

        assertNotNull(configuration);
        assertTrue(configuration.getDialectConfigurations().isEmpty());
        assertTrue(configuration.getDialects().isEmpty());
        assertFalse(configuration.isStandardDialectPresent());
        assertNull(configuration.getStandardDialectPrefix());
        assertTrue(configuration.getExecutionAttributes().isEmpty());
        assertNull(configuration.getExpressionObjectFactory().getAllExpressionObjectNames());
        assertNull(configuration.getExpressionObjectFactory().buildObject(null, "anything"));
        assertFalse(configuration.getExpressionObjectFactory().isCacheable("anything"));

        assertNotNull(configuration.getElementDefinitions());
        assertNotNull(configuration.getAttributeDefinitions());

        for (final TemplateMode templateMode : TemplateMode.values()) {
            assertTrue(configuration.getTemplateBoundariesProcessors(templateMode).isEmpty());
            assertTrue(configuration.getCDATASectionProcessors(templateMode).isEmpty());
            assertTrue(configuration.getCommentProcessors(templateMode).isEmpty());
            assertTrue(configuration.getDocTypeProcessors(templateMode).isEmpty());
            assertTrue(configuration.getElementProcessors(templateMode).isEmpty());
            assertTrue(configuration.getProcessingInstructionProcessors(templateMode).isEmpty());
            assertTrue(configuration.getTextProcessors(templateMode).isEmpty());
            assertTrue(configuration.getXMLDeclarationProcessors(templateMode).isEmpty());
            assertTrue(configuration.getPreProcessors(templateMode).isEmpty());
            assertTrue(configuration.getPostProcessors(templateMode).isEmpty());
