                "second", names("secondOnly", "shared"), false);

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(new TestExpressionObjectDialect("expr1", first)),
                new DialectConfiguration(new TestExpressionObjectDialect("expr2", second))));

