    private static Set<DialectConfiguration> configurations(final DialectConfiguration... dialectConfigurations) {
        return new LinkedHashSet<DialectConfiguration>(Arrays.asList(dialectConfigurations));
    }

    private static Set<IProcessor> processors(final IProcessor... processors) {
        return new LinkedHashSet<IProcessor>(Arrays.asList(processors));
    }

    private static Set<IPreProcessor> preProcessors(final IPreProcessor... processors) {
        return new LinkedHashSet<IPreProcessor>(Arrays.asList(processors));
    }

    private static Set<IPostProcessor> postProcessors(final IPostProcessor... processors) {
        return new LinkedHashSet<IPostProcessor>(Arrays.asList(processors));
    }

    private static TestProcessorDialect processorDialect(
            final String name, final String prefix, final int precedence, final IProcessor... dialectProcessors) {
        return new TestProcessorDialect(name, prefix, precedence, new Function<String, Set<IProcessor>>() {
            public Set<IProcessor> apply(final String requestedPrefix) {
                return processors(dialectProcessors);
            }
        });
    }

    private static Set<String> names(final String... names) {
        return new LinkedHashSet<String>(Arrays.asList(names));
    }

    private static List<String> labels(final Set<? extends IProcessor> processors) {
        final List<String> labels = new ArrayList<String>(processors.size());
        for (final IProcessor processor : processors) {
            labels.add(processor.toString());
        }
        return labels;
    }

    private static boolean containsInstanceOf(final Set<?> objects, final Class<?> type) {
        for (final Object object : objects) {
            if (type.isInstance(object)) {
                return true;
            }
        }
        return false;
    }

    private static List<IProcessor> allProcessors(final DialectSetConfiguration configuration, final TemplateMode templateMode) {
        final List<IProcessor> all = new ArrayList<IProcessor>();
        all.addAll(configuration.getTemplateBoundariesProcessors(templateMode));
        all.addAll(configuration.getCDATASectionProcessors(templateMode));
        all.addAll(configuration.getCommentProcessors(templateMode));
        all.addAll(configuration.getDocTypeProcessors(templateMode));
        all.addAll(configuration.getElementProcessors(templateMode));
        all.addAll(configuration.getProcessingInstructionProcessors(templateMode));
        all.addAll(configuration.getTextProcessors(templateMode));
        all.addAll(configuration.getXMLDeclarationProcessors(templateMode));
        return all;
    }



