    @Test
    public void queuesEventsWhileStoppedAndProcessesThemOnHandlePending() {

        final Harness harness = new Harness(HTML, Collections.<IProcessor>singletonList(
                textProcessor(100, new TextAction() {
                    public void execute(final ITemplateContext context, final IText text, final ITextStructureHandler structureHandler) {
                        structureHandler.setText("[" + text.getText() + "]");
                    }
                })));
        final IModelFactory modelFactory = harness.context.getModelFactory();
        final TemplateFlowController flowController = new TemplateFlowController();

        harness.handler.setFlowController(flowController);

        harness.handler.handleTemplateStart(TemplateStart.TEMPLATE_START_INSTANCE);
        harness.handler.handleOpenElement(modelFactory.createOpenElementTag("p"));

        flowController.stopProcessing = true;
        harness.handler.handleText(modelFactory.createText("x"));

        // The event was queued, not processed
        assertTrue(flowController.processorTemplateHandlerPending);
        assertEquals(2, harness.next.events.size());

        // Still stopped: nothing is processed
        harness.handler.handlePending();
        assertTrue(flowController.processorTemplateHandlerPending);
        assertEquals(2, harness.next.events.size());

        // Processing resumed: the queued event is processed (processors still apply)
        flowController.stopProcessing = false;
        harness.handler.handlePending();
        assertFalse(flowController.processorTemplateHandlerPending);
        assertEquals(3, harness.next.events.size());

        harness.handler.handleCloseElement(modelFactory.createCloseElementTag("p"));
        harness.handler.handleTemplateEnd(TemplateEnd.TEMPLATE_END_INSTANCE);

        assertEquals("<p>[x]</p>", harness.next.output());
        assertEquals(0, harness.context.level());

    }


    @Test
    public void enablesThrottlingWhenTheFlowControllerIsSetBeforeTheContext() {

        final Harness harness = new Harness(HTML, Collections.<IProcessor>singletonList(
                textProcessor(100, new TextAction() {
