    @Test
    public void honorsTheProcessableFlagOfBodiesSetByElementProcessors() {

        final Harness processableHarness = new Harness(HTML, Arrays.<IProcessor>asList(
                tagProcessor("action", 100, new ElementTagAction() {
                    public void execute(final ITemplateContext context, final IProcessableElementTag tag, final IElementTagStructureHandler structureHandler) {
                        structureHandler.setBody("BODY", true);
                    }
                }),
                textProcessor(100, new TextAction() {
                    public void execute(final ITemplateContext context, final IText text, final ITextStructureHandler structureHandler) {
                        structureHandler.setText("[" + text.getText() + "]");
                    }
                })));

        processableHarness.process("<div t:action=\"1\">body</div>");

        // processable = true: the new body is processed by the handler itself (text processors apply)
        assertEquals("<div t:action=\"1\">[BODY]</div>", processableHarness.next.output());


        final Harness nonProcessableHarness = new Harness(HTML, Arrays.<IProcessor>asList(
                tagProcessor("action", 100, new ElementTagAction() {
                    public void execute(final ITemplateContext context, final IProcessableElementTag tag, final IElementTagStructureHandler structureHandler) {
                        structureHandler.setBody("BODY", false);
                    }
                }),
                textProcessor(100, new TextAction() {
                    public void execute(final ITemplateContext context, final IText text, final ITextStructureHandler structureHandler) {
                        structureHandler.setText("[" + text.getText() + "]");
                    }
                })));

        nonProcessableHarness.process("<div t:action=\"1\">body</div>");

        // processable = false: the new body is executed directly by the next handler in the chain
        assertEquals("<div t:action=\"1\">BODY</div>", nonProcessableHarness.next.output());

    }


