    private static void process(
            final ProcessorTemplateHandler handler, final ITemplateContext context, final String markup) {

        final IModelFactory modelFactory = context.getModelFactory();
        final TemplateData templateData = new TemplateData(
                "test-template", null, new StringTemplateResource(markup),
                context.getTemplateMode(), null);
        final IModel model = modelFactory.parse(templateData, markup);
        ((TemplateModel) model).process(handler);

    }


    private static Object invokeDelegate(
            final ITemplateContext delegate, final Method method, final Object[] args) throws Throwable {
        try {
            return method.invoke(delegate, args);
        } catch (final InvocationTargetException e) {
            throw e.getTargetException();
        }
    }


    private static final class Harness {

        private final IEngineConfiguration configuration;
        private final TemplateData templateData;
        private final EngineContext context;
        private final ProcessorTemplateHandler handler;
        private final RecordingTemplateHandler next;

        private Harness(final TemplateMode templateMode, final List<IProcessor> processors) {

            final TemplateEngine engine = new TemplateEngine();
            final StringTemplateResolver resolver = new StringTemplateResolver();
            resolver.setTemplateMode(templateMode);
            engine.setTemplateResolver(resolver);
            // Note "setDialect" replaces the default (Standard) dialect, so that only the
            // processors specified for the test are executed.
            engine.setDialect(new TestProcessorDialect(processors));
            this.configuration = engine.getConfiguration();

            this.templateData = new TemplateData(
                    "test-template", null, new StringTemplateResource("<test/>"), templateMode, null);
            this.context = new EngineContext(
                    this.configuration, this.templateData, null, Locale.US, new HashMap<String, Object>());

            this.handler = new ProcessorTemplateHandler();
            this.next = new RecordingTemplateHandler();
            this.handler.setContext(this.context);
            this.handler.setNext(this.next);

        }

        private void process(final String markup) {
            final IModel model = this.context.getModelFactory().parse(this.templateData, markup);
            ((TemplateModel) model).process(this.handler);
        }

    }


    private static final class TestProcessorDialect implements IProcessorDialect {

        private final List<IProcessor> processors;

        private TestProcessorDialect(final List<IProcessor> processors) {
            this.processors = new ArrayList<IProcessor>(processors);
        }

        public String getPrefix() {
            return DIALECT_PREFIX;
        }

        public int getDialectProcessorPrecedence() {
            return 0;
        }

        public Set<IProcessor> getProcessors(final String dialectPrefix) {
            return new LinkedHashSet<IProcessor>(this.processors);
        }

        public String getName() {
            return "ProcessorTemplateHandlerTestDialect";
        }

    }


    private static final class RecordingTemplateHandler extends AbstractTemplateHandler {

        private final List<ITemplateEvent> events = new ArrayList<ITemplateEvent>();
        private final StringBuilder output = new StringBuilder();

        private void record(final ITemplateEvent event) {
            this.events.add(event);
            try {
                final Writer writer = new StringWriter();
                event.write(writer);
                this.output.append(writer.toString());
            } catch (final Exception e) {
                throw new IllegalStateException(e);
            }
        }

        private String output() {
            return this.output.toString();
        }

        @Override
        public void handleTemplateStart(final ITemplateStart templateStart) {
            record(templateStart);
        }

        @Override
        public void handleTemplateEnd(final ITemplateEnd templateEnd) {
            record(templateEnd);
        }

        @Override
        public void handleXMLDeclaration(final IXMLDeclaration xmlDeclaration) {
            record(xmlDeclaration);
        }

        @Override
        public void handleDocType(final IDocType docType) {
            record(docType);
        }

        @Override
        public void handleCDATASection(final ICDATASection cdataSection) {
            record(cdataSection);
        }

        @Override
        public void handleComment(final IComment comment) {
            record(comment);
        }

        @Override
        public void handleText(final IText text) {
            record(text);
        }

        @Override
        public void handleStandaloneElement(final IStandaloneElementTag standaloneElementTag) {
            record(standaloneElementTag);
        }

        @Override
        public void handleOpenElement(final IOpenElementTag openElementTag) {
            record(openElementTag);
        }

        @Override
        public void handleCloseElement(final ICloseElementTag closeElementTag) {
            record(closeElementTag);
        }

        @Override
        public void handleProcessingInstruction(final IProcessingInstruction processingInstruction) {
            record(processingInstruction);
        }

    }


